from qiskit import QuantumCircuit

def build_oracle(qc: QuantumCircuit, problem_qubits: list[int],
                 ancilla_qubits: list[int]) -> None:
    """
    Grover phase oracle for the pattern "01110" appearing as a contiguous
    substring (length 5) in a binary text of length 7.
    """
    pattern = [0, 1, 1, 1, 0]
    a = ancilla_qubits  # 4 ancillas: a[0] final OR, a[1..3] flags for offsets 0,1,2

    # ---------- compute flags ----------
    for offset in range(3):
        flag_anc = a[offset + 1]
        qubits = problem_qubits[offset:offset+5]

        # Flip pattern bits so that match becomes all 0
        for i in range(5):
            if pattern[i] == 1:
                qc.x(qubits[i])

        # Flip all qubits so that match becomes all 1
        for i in range(5):
            qc.x(qubits[i])

        # Set flag if all five qubits are 1 (i.e. match)
        qc.mcx(qubits, flag_anc, mode='noancilla')

        # Undo all flips
        for i in range(5):
            qc.x(qubits[i])
        for i in range(5):
            if pattern[i] == 1:
                qc.x(qubits[i])

    # ---------- OR the three flags into a[0] ----------
    # OR(a,b,c) = NOT( (NOT a) AND (NOT b) AND (NOT c) )
    for i in range(1, 4):
        qc.x(a[i])
    qc.mcx([a[1], a[2], a[3]], a[0], mode='noancilla')
    qc.x(a[0])
    for i in range(1, 4):
        qc.x(a[i])

    # ---------- apply phase ----------
    qc.z(a[0])

    # ---------- uncompute OR (self-inverse) ----------
    for i in range(1, 4):
        qc.x(a[i])
    qc.mcx([a[1], a[2], a[3]], a[0], mode='noancilla')
    qc.x(a[0])
    for i in range(1, 4):
        qc.x(a[i])

    # ---------- uncompute flags (reverse order) ----------
    for offset in range(2, -1, -1):
        flag_anc = a[offset + 1]
        qubits = problem_qubits[offset:offset+5]

        # Same sequence as in compute (each step is self-inverse)
        for i in range(5):
            if pattern[i] == 1:
                qc.x(qubits[i])
        for i in range(5):
            qc.x(qubits[i])
        qc.mcx(qubits, flag_anc, mode='noancilla')
        for i in range(5):
            qc.x(qubits[i])
        for i in range(5):
            if pattern[i] == 1:
                qc.x(qubits[i])

    # All ancilla qubits are now back to |0>
